import os
import json
from typing import Dict, Any
from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeResult

def safe_str(field: Dict[str, Any]) -> str:
    return field.get('content', '') if isinstance(field, dict) else str(field)

def safe_float(field: Dict[str, Any]) -> float:
    try:
        content = field.get('content', '0') if isinstance(field, dict) else '0'
        return float(content)
    except (ValueError, TypeError):
        return 0.0

def extract_and_normalize_expenses(document_path: str) -> Dict[str, Any]:
    endpoint = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_KEY")
    if not endpoint or not key:
        raise ValueError("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY must be set")

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    with open(document_path, "rb") as f:
        poller = client.begin_analyze_document("prebuilt-invoice", analyze_request=f, content_type="application/octet-stream")

    result: AnalyzeResult = poller.result()

    if not result.documents:
        return {}

    doc = result.documents[0].fields

    standard = {
        "invoice_id": safe_str(doc.get("InvoiceId", {})),
        "vendor_name": safe_str(doc.get("VendorName", {})),
        "vendor_address": safe_str(doc.get("VendorAddress", {})),
        "invoice_date": safe_str(doc.get("InvoiceDate", {})),
        "due_date": safe_str(doc.get("DueDate", {})),
        "subtotal": safe_float(doc.get("SubTotal", {})),
        "tax": safe_float(doc.get("Tax", {})),
        "total_amount": safe_float(doc.get("Total", {})),
        "amount_due": safe_float(doc.get("AmountDue", {})),
        "line_items": []
    }

    items = doc.get("Items", {})
    if items and items.type == "list":
        for item in items.value:
            line_item = {
                "description": safe_str(item.get("Description", {})),
                "quantity": safe_float(item.get("Quantity", {})),
                "unit_price": safe_float(item.get("UnitPrice", {})),
                "amount": safe_float(item.get("Amount", {}))
            }
            standard["line_items"].append(line_item)

    return standard
